import { test } from 'node:test';
import assert from 'node:assert/strict';
import { contador } from './solution.mjs';

test('contador começa em zero', () => {
  assert.equal(contador.obterValor(), 0);
});

test('incrementar acumula um por um', () => {
  assert.equal(contador.incrementar(), 1);
  assert.equal(contador.incrementar(), 2);
  assert.equal(contador.incrementar(), 3);
  assert.equal(contador.obterValor(), 3);
});

test('zerar volta o contador para zero', () => {
  contador.zerar();
  assert.equal(contador.obterValor(), 0);
  assert.equal(contador.incrementar(), 1);
});

solutionCode:
export const contador = (function () {
  let valor = 0;
  return {
    incrementar: function () {
      valor += 1;
      return valor;
    },
    obterValor: function () {
      return valor;
    },
    zerar: function () {
      valor = 0;
    },
  };
})();
